def bots_to_networks(apps, schema_editor):
    """A bot marked «Бот всей сети» becomes its network's bot (the first one
    by creation if several were marked)."""

    BotInstance = apps.get_model("partners", "BotInstance")
    Network = apps.get_model("partners", "Network")
    for bot in BotInstance.objects.filter(
        serves_network=True, partner__network__isnull=False
    ).order_by("created_at"):
        Network.objects.filter(id=bot.partner.network_id, bot__isnull=True).update(bot=bot)


def networks_to_bots(apps, schema_editor):
    BotInstance = apps.get_model("partners", "BotInstance")
    Network = apps.get_model("partners", "Network")
    BotInstance.objects.filter(
        id__in=Network.objects.filter(bot__isnull=False).values("bot_id")
    ).update(serves_network=True)


